function icon(k,size=16){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.info}"/></svg>`}
const badge=(text,tone='')=>`<span class="badge ${tone}">${text}</span>`;
const btn=(text,target,tone='')=>`<button class="btn ${tone}" onclick="showView('${target}')">${text}${icon('arrow',13)}</button>`;
const footer=()=>`<footer class="footer"><span>品牌、文章与全部指标均为虚构示例；平台差异不代表平台固有偏好。</span><span>GeniLink / Prototype v1</span></footer>`;
function head(eyebrow,title,sub,buttons=''){return `<div class="head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><div class="sub">${sub}</div></div><div class="buttons">${buttons}</div></div>`}
function metric(label,value,hint,color=''){return `<div class="panel metric"><label>${label}</label><div class="value ${color}">${value}</div><div class="hint">${hint}</div></div>`}
function table(headers,rows){return `<table class="table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`}
function tr(cells,cls='',attrs=''){return `<tr class="${cls}" ${attrs}>${cells.map(x=>`<td>${x}</td>`).join('')}</tr>`}
function overview(){return head('AUDIT / A-1013','把可见性结果变成下一步行动','20 个提示词 · 3 个平台 · 每题 3 轮采样 · 本期审计 2026.10.13',btn('同题跨平台对照','platforms','primary'))+`<div class="grid4">${metric('有效平台回答','174 <small>/ 180</small>','6 条采集失败 · 不计入表现分母')}${metric('我方品牌提及率','49%','86 / 174 条有效回答','teal')}${metric('我方品牌推荐率','29%','51 / 174 条明确推荐','purple')}${metric('新发现实体','4 <small>个</small>','3 个回答内出现 · 1 个仅来源出现')}</div><div class="notice">${icon('info')}<div><strong>基础结果已完成，原文证据持续补齐</strong> · 72 篇来源文章：54 篇全文、6 篇部分正文、8 篇访问受限、4 篇待处理。</div><button class="textbtn right" onclick="showView('sources')">采集覆盖 →</button></div><div class="split"><section class="panel pad"><div class="sectionhead"><h2>本期最值得处理的 3 件事</h2>${badge('按价值与可执行性排序','purple')}</div>${[['01','补齐高温工况案例与适用边界','DeepSeek · 案例信息缺口，候选竞品拓域反复出现','平台专项','blue','actions'],['02','纠正旧版参数，统一对外事实','千问 · 已推荐我方，部分回答仍采用 2024 版参数','事实纠错','red','evidence'],['03','补充价格范围、配置条件与询价入口','Kimi · 比较侧重价格，我方公开信息不完整','网站优化','teal','actions']].map(([n,t,d,l,c,to])=>`<div class="risk"><span class="risknum">${n}</span><div class="desc"><h3>${t}</h3><p>${d}</p><p style="margin-top:7px">${badge(l,c)} ${badge(n==='02'?'事实已核实':'素材待确认',n==='02'?'teal':'amber')}</p></div><button class="textbtn" onclick="${n==='02'?"state.platform='千问';":''}showView('${to}')">查看 →</button></div>`).join('')}</section><section class="panel pad"><div class="sectionhead"><h2>每个平台的问题不同</h2><button class="textbtn" onclick="showView('platforms')">展开对照 →</button></div>${['DeepSeek|29|10|缺少案例证据','千问|70|52|参数事实过时','Kimi|48|25|价格信息缺口'].map(x=>{let [p,m,r,g]=x.split('|');return `<div style="margin:15px 0 21px"><div class="meterline"><b>${p}</b><span>${g}</span></div><div class="bar"><span style="width:${m}%"></span></div><div class="meterline"><span>提及 ${m}%</span><span>推荐 ${r}%</span></div></div>`}).join('')}<div class="inspect"><strong>决策提醒</strong>优化任务和效果逐平台追踪，总体提及率不能代替平台专项诊断。</div></section></div><section class="panel pad gap"><div class="sectionhead"><h2>从发现到验证</h2><span class="sub">每一步保留证据与状态</span></div><div class="grid4">${[['brands','发现新品牌','拓域是新出现的候选竞品'],['evidence','核对回答与原文','查找支持、冲突与缺失信息'],['brief','执行内容改进','使用已确认材料与事实'],['measure','查看平台效果','分别观察上升、持平和下降']].map((a,i)=>`<button onclick="showView('${a[0]}')" style="text-align:left;border-left:2px solid ${i===0?'var(--teal)':'#3a4053'};padding:0 15px"><div class="sub">0${i+1}</div><h3 style="margin:7px 0">${a[1]}</h3><div class="sub">${a[2]}</div></button>`).join('')}</div></section>`}
const platformData={DeepSeek:{letter:'D',color:'blue',ver:'58 条有效回答 / 60 次采样',status:'缺少我方支撑信息',tone:'amber',brands:[['锐川','明确推荐 · 第 1 位'],['拓域','明确推荐 · 第 2 位'],['云衡','本条未提及']],answer:'建议核对稳定性测试和长期运行案例。锐川、拓域有相关案例说明，还需结合安装环境评估。',sources:'《高温工况选型与运行案例》<br>《工业监测设备对比测评》',evidence:'4 篇相关来源 · 3 篇全文可核验',hyp:'补齐经产品团队确认的案例与适用边界',goal:'相关提示词的我方推荐率'},'千问':{letter:'Q',color:'purple',ver:'60 条有效回答 / 60 次采样',status:'推荐我方，但参数过时',tone:'red',brands:[['云衡','明确推荐 · 第 1 位'],['锐川','比较对象'],['拓域','本条未提及']],answer:'云衡适合高温设备监测，可在 120℃ 条件下使用；选择时注意安装与维护要求。',sources:'《云衡产品介绍（2024 版）》<br>《高温设备监测选型指南》',evidence:'2 个参数冲突 · 品牌事实已核实',hyp:'更新旧版参数和可公开的测试条件',goal:'已核验参数的事实准确率'},Kimi:{letter:'K',color:'teal',ver:'56 条有效回答 / 60 次采样',status:'价格比较中的信息缺口',tone:'blue',brands:[['锐川','明确推荐 · 顺序未提供'],['云衡','提及 · 未明确推荐'],['星澜','仅作为渠道出现']],answer:'应综合比较预算、配置和售后。锐川有公开配置价格，云衡需要进一步询价确认适用范围。',sources:'《工业监测方案价格与配置》<br>《企业采购选型问答》',evidence:'3 篇来源 · 1 篇部分正文',hyp:'完善真实价格范围与配置边界，保留询价入口',goal:'推荐率与价格描述完整性'}};
function platforms(){return head('PLATFORM COMPARISON','同一个问题，分别看清各平台','按提示词版本、平台与采样条件对照；下方展示同一轮回答。',btn('查看优化行动','actions','primary'))+`<div class="panel pad"><div class="row" style="align-items:center">${badge('选型场景','purple')}<strong class="grow" style="font-size:16px">高温工况下，如何选择工业监测方案？</strong><select class="select" aria-label="采样轮次" onchange="toast('原型仅提供第 1 轮示例，其余轮次在正式系统中分别保存')"><option>采样第 1 轮</option><option>采样第 2 轮</option><option>采样第 3 轮</option></select></div><div class="coverage" style="margin-top:10px"><span>提示词 P-07 · v1</span><span>2026.10.13 · 搜索模式开启</span><span>账号条件未完整确认 · 可比性待核实</span></div></div><div class="grid3 gap">${Object.entries(platformData).map(([name,d])=>`<section class="panel"><div class="platformhead"><span class="platformlogo" style="color:var(--${d.color})">${d.letter}</span><div><h3>${name}</h3><small>${d.ver}</small></div></div><div class="platformbody">${badge(d.status,d.tone)}<div class="key">本条回答中的品牌</div>${d.brands.map(([n,s])=>`<div class="brandline"><b class="${n==='云衡'?'teal':''}">${n}</b><span>${s}</span></div>`).join('')}<div class="key">回答关键片段</div><div class="quote" style="padding:12px;min-height:112px;font-size:12px">${d.answer}</div><div class="key">平台展示的来源文章</div><p>${d.sources}</p><div class="hint">${d.evidence}</div><div class="hypothesis"><b>针对该平台的待验证方向</b>${d.hyp}<p style="margin:6px 0 0;font-size:11px">复测指标：${d.goal}</p></div><button class="btn small" style="width:100%;margin-top:14px" onclick="state.platform='${name}';showView('evidence')">查看对应原文证据 ${icon('arrow',12)}</button></div></section>`).join('')}</div><div class="notice warn">${icon('info')}<div>差异是本轮观察结果，不能归因为平台固定偏好。重复采样并确认条件一致后，才判断稳定差异。</div></div><section class="panel pad"><div class="sectionhead"><h2>共性与专项分别落地</h2>${badge('同一资产可关联多个平台目标')}</div><div class="grid3"><div><div class="key">共性信息需求</div><p class="sub">公开、准确的适用边界与测试条件</p></div><div><div class="key">不同优化目标</div><p class="sub">案例证明 / 参数纠错 / 价格配置</p></div><div><div class="key">执行原则</div><p class="sub">品牌事实一致，效果逐平台复测</p></div></div></section>`}
