function sources(){let rows=articles.filter(x=>state.sourceStatus==='all'||x[4]===state.sourceStatus);return head('SOURCE LIBRARY','来源文章库','保存原文快照、引用关系和分析证据；文章更新后保留历史版本。',`<button class="btn" onclick="toast('示例：已将受限来源加入人工补采列表')">重试 / 补充采集</button>`)+`<section class="panel pad"><div class="sectionhead"><h2>原文采集覆盖</h2><span class="sub">72 篇唯一文章 · 全文可评估 54 篇</span></div><div class="stack"><span style="width:75%;background:var(--teal)"></span><span style="width:8.33%;background:var(--amber)"></span><span style="width:11.11%;background:var(--red)"></span><span style="width:5.56%;background:#57617d"></span></div><div class="legend"><span class="teal">● 全文 54</span><span class="amber">● 部分正文 6</span><span class="red">● 访问受限 8</span><span>● 待处理 4</span><span class="right">全部 72 个来源链接均已登记</span></div></section><div class="tabs gap"><button class="${state.sourceStatus==='all'?'active':''}" onclick="state.sourceStatus='all';showView('sources')">全部文章</button>${['全文','部分正文','访问受限','待处理'].map(s=>`<button class="${state.sourceStatus===s?'active':''}" onclick="state.sourceStatus='${s}';showView('sources')">${s}</button>`).join('')}</div><div class="toolbar"><input class="search" aria-label="搜索来源" placeholder="搜索标题、域名或品牌" oninput="filterRows(this.value,'sourcerow')"><select class="select" aria-label="平台筛选" onchange="filterRows(this.value==='all'?'':this.value,'sourcerow')"><option value="all">全部平台</option><option>DeepSeek</option><option>千问</option><option>Kimi</option></select><span class="sub right">当前示例：回答关联来源</span></div><div class="panel">${table(['文章 / 来源','平台','采集状态','我方品牌','其他品牌','证据发现'],rows.map(a=>tr([`<button class="textbtn" style="color:var(--text);text-align:left" onclick="openArticle('${a[0]}','${a[3]}','${a[4]}')">${a[0]}</button><small>${a[1]} · ${a[2]}</small>`,a[3],badge(a[4],a[5]),badge(a[6],a[6]==='已发现'?'teal':a[6]==='无法判断'?'amber':''),a[7],`<span class="${a[8]==='参数冲突'?'red':''}">${a[8]}</span>`],'','data-row="sourcerow"')))}<div class="footnote">显示 6 条代表性示例。部分正文未命中品牌时为“无法判断”，不能当作品牌缺席。</div></div><div class="grid3 gap">${[['文章级版本','内容变化保存新快照，历史审计保留关联版本和获取时间。'],['转载与独立证据','相似文章归为同一内容族，保留各自 URL，避免重复计算。'],['来源类型区分','回答引用、搜索候选和推断来源分别标记，候选不计为实际引用。']].map(([t,d])=>`<div class="panel pad"><h3>${t}</h3><p class="sub">${d}</p></div>`).join('')}</div>`}
const evidenceData={DeepSeek:{title:'高温工况的案例与测试条件',source:'高温工况选型与运行案例',url:'review.example.com / thermal-case',relation:'同义支持',tone:'teal',answer:'应核对测试条件、连续运行记录和适用边界。<mark>锐川、拓域均有相关案例可供参考</mark>，还应结合安装环境评估。',paragraph:'案例介绍应提供温度、持续运行时间和安装方式。<mark>拓域的公开案例列出了连续运行记录与工况限制</mark>，结论只适用于所描述的条件。',fact:'该段支持“有公开案例”的回答观点；我方未在本条回答出现。',hyp:'案例信息缺口可能影响这一场景的表现，现有数据不能确定原因。',missing:'我方可公开案例和测试记录尚需产品负责人确认。'},'千问':{title:'回答采用旧版参数，需核实纠错',source:'云衡产品介绍（2024 版）',url:'industry.example.com / yunheng-2024',relation:'与当前确认事实冲突',tone:'red',answer:'云衡适用于高温设备监测。公开介绍显示其<mark class="bad">最高适用温度为 120℃</mark>，选型还需确认安装环境。',paragraph:'云衡 YH-20 产品规格（2024 年）：<mark class="bad">建议适用温度范围为 0–120℃</mark>。具体运行环境与配置应向供应商确认。',fact:'回答与历史文章参数一致。项目已核实的新规格为 0–150℃，并有明确安装限定。',hyp:'旧文章可能提供支持，应更新对外参数并提交可核验纠错资料。',missing:'尚不清楚平台刷新来源的时间，不能保证更新后回答立即改变。'},Kimi:{title:'价格比较中，我方信息边界不完整',source:'工业监测方案价格与配置',url:'guide.example.com / pricing',relation:'部分支持',tone:'amber',answer:'应比较预算、配置与售后。<mark>锐川提供公开配置价格，云衡建议进一步询价</mark>确认报价包含项目。',paragraph:'报价需结合传感器数量、安装环境和服务范围比较。<mark>锐川列出了标准配置价格示例</mark>。本文未收录云衡的完整价格范围。',fact:'来源包含竞品配置价格，未提供我方完整价格范围。',hyp:'公开准确价格范围、配置边界及询价方式，可能提升信息完整性。',missing:'可公开报价范围与有效期需销售及产品团队确认。'}};
function evidence(){const d=evidenceData[state.platform];return head('EVIDENCE / P-07','逐个观点核对原文证据','高温工况下，如何选择工业监测方案？ · 回答与文章版本分别保存。',btn('关联优化行动','actions','primary'))+`<div class="tabs">${Object.keys(evidenceData).map(p=>`<button class="${state.platform===p?'active':''}" onclick="state.platform='${p}';showView('evidence')">${p}</button>`).join('')}</div><div class="row" style="align-items:center;margin-bottom:16px"><h2 class="grow">${d.title}</h2>${badge(d.relation,d.tone)}${badge('人工核对示例','purple')}</div><div class="grid2"><section class="panel"><div class="evidencehead">${icon('platforms')}<b>${state.platform} · 原始回答</b><span class="sub right">第 1 轮</span></div><div class="pad"><div class="sub">回答采集：2026.10.13 10:32 · 内容完整</div><div class="quote" style="margin:14px 0;min-height:184px"><span class="code">回答 §02</span><p>${d.answer}</p></div><div class="kv"><span>关联来源卡片</span><span>引用 [2] · 标题和链接已采集</span></div><div class="kv"><span>涉及实体</span><span class="teal">${state.platform==='DeepSeek'?'锐川 · 拓域':'云衡 · 锐川'}</span></div></div></section><section class="panel"><div class="evidencehead">${icon('sources')}<b>来源原文 · 快照 v1</b>${badge('后补版本','amber')}</div><div class="pad"><strong>${d.source}</strong><div class="code" style="margin-top:4px">${d.url}</div><div class="sub" style="margin-top:8px">正文获取：2026.10.13 10:48 · 全文可评估</div><div class="quote" style="margin:14px 0;min-height:143px"><span class="code">原文 §05</span><p>${d.paragraph}</p></div><button class="textbtn" onclick="openSnapshot()">打开持久化原文 →</button></div></section></div><div class="notice warn">${icon('info')}<div>文章获取晚于回答采集。原文支持关系不证明平台实际使用该段，也不能证明模型当时看到的版本完全相同。</div></div><div class="grid3">${[['01 / 已观测事实',d.fact,'teal'],['02 / 诊断假设',d.hyp,'purple'],['03 / 尚缺信息',d.missing,'amber']].map(([t,p,c])=>`<section class="panel pad"><div class="key ${c}" style="margin:0 0 10px">${t}</div><p style="font-size:12px">${p}</p></section>`).join('')}</div><section class="panel pad gap"><div class="sectionhead"><h2>支持、冲突与待核实项</h2><span class="sub">结论始终关联原始证据</span></div><div class="claim">${badge('E-07-01')}<div class="text">回答观点与原文段落的对应关系</div>${badge(d.relation,d.tone)}</div><div class="claim">${badge('E-07-02')}<div class="text">我方可公开产品材料与限定条件</div>${badge(state.platform==='千问'?'事实已核实':'材料待核实',state.platform==='千问'?'teal':'amber')}</div><div class="claim">${badge('E-07-03')}<div class="text">某一来源是否造成平台回答变化</div>${badge('无法确认')}</div></section>`}
const actionData=[{id:'ACT-01',title:'补齐高温工况案例、测试条件与适用边界',scope:'specific',label:'平台专项',platform:'DeepSeek',status:'素材待确认',asset:'官网 / 工况案例页（新增）',material:'真实案例、测试环境、连续运行记录、授权范围',goal:'相关问题推荐率；同时观察千问与 Kimi',owner:'内容团队 + 产品负责人',cost:'中等工作量',proof:'4 条证据 · P-07 / P-09',eligible:false,desc:'相关回答推荐竞品，来源文章有公开案例。我方对应材料尚未确认。'},{id:'ACT-02',title:'统一规格页与历史来源的产品参数',scope:'common',label:'共性资产改进',platform:'千问主目标 · 全平台回归',status:'事实已核实',asset:'官网 / 产品规格页（更新）',material:'已审核参数表、安装条件与生效日期',goal:'千问参数准确性；其他平台的参数回归检查',owner:'产品负责人 + 内容团队',cost:'低工作量',proof:'2 条冲突证据 · P-07',eligible:true,desc:'千问采用旧版参数。更新同一规格页，并向历史来源提交可核验纠错材料。'},{id:'ACT-03',title:'补充价格范围、配置条件和询价入口',scope:'specific',label:'平台专项',platform:'Kimi',status:'销售材料待确认',asset:'官网 / 价格与配置页（更新）',material:'价格区间、配置项、有效期与服务边界',goal:'价格类问题推荐率与信息完整性',owner:'销售负责人 + 网站团队',cost:'中等工作量',proof:'3 条证据 · P-03 / P-07',eligible:false,desc:'价格比较中，我方公开条件不足。先确认可公开信息，再修改价格说明页。'}];
function actions(){return head('ACTION CENTER','每条优化建议，都有证据和验收目标','共性资产统一执行，平台诊断和复测目标分别保留。',btn('查看效果复测','measure'))+`<div class="grid4">${metric('待推进行动','3','按证据、场景价值与工作量排序')}${metric('平台专项','2','DeepSeek 案例 / Kimi 价格','blue')}${metric('可创建内容方案','1','事实与素材已经核实','teal')}${metric('材料核实任务','2','先收集素材与确认事实','amber')}</div><div class="tabs gap">${[['all','全部行动'],['specific','平台专项'],['common','共性资产改进']].map(([v,l])=>`<button class="${state.actionScope===v?'active':''}" onclick="state.actionScope='${v}';showView('actions')">${l}</button>`).join('')}</div>${actionData.filter(a=>state.actionScope==='all'||a.scope===state.actionScope).map(a=>`<section class="actioncard"><div class="row" style="justify-content:space-between"><div>${badge(a.label,a.scope==='common'?'teal':'blue')} ${badge(a.platform)} <span class="hint" style="margin-left:8px">${a.id}</span></div>${badge(a.status,a.eligible?'teal':'amber')}</div><h3>${a.title}</h3><p>${a.desc}</p><div class="actionmeta"><span>负责人：${a.owner}</span><span>${a.cost}</span><button class="textbtn" onclick="state.platform='${a.id==='ACT-01'?'DeepSeek':a.id==='ACT-02'?'千问':'Kimi'}';showView('evidence')">${a.proof} →</button></div><details ${a.eligible?'open':''}><summary>修改对象、素材与复测目标</summary><div class="taskdetail" style="margin-top:12px"><div class="line"><label>修改资产</label><span>${a.asset}</span></div><div class="line"><label>所需素材</label><span>${a.material}</span></div><div class="line"><label>复测目标</label><span>${a.goal}</span></div><div class="line"><label>验收标准</label><span>事实准确、公开可访问、记录发布 URL 与版本</span></div></div></details><div class="actionfoot"><span class="sub">${a.eligible?'发布资产后再判断平台效果':'材料审核通过后才能转正式内容方案'}</span>${a.eligible?btn('创建内容方案','brief','primary'):`<button class="btn small" onclick="toast('示例：已创建素材核实任务，原型不写入业务系统')">创建素材核实任务</button>`}</div></section>`).join('')}<div class="notice warn">${icon('info')}<span>平台证据冲突时先核实，避免生成矛盾事实；任务完成与平台效果改善分别记录。</span></div>`}
function brief(){return head('CONTENTOS / BRIEF','把证据转为可执行的内容方案','来自 ACT-02 · 更新产品规格页 · 保留事实来源、限定条件与平台目标。',`<button class="btn" onclick="showView('actions')">返回优化行动</button><button class="btn primary" onclick="createBrief()">${state.briefCreated?'查看已创建草稿':'创建方案草稿'}</button>`)+`<div class="flow"><b class="active">① 核对来源与事实</b><span>→</span><b>② 创作 / 修改</b><span>→</span><b>③ 审核发布</b><span>→</span><b>④ 关联复测</b></div><div class="notice">${icon('check')}<span>参数和安装条件已核实。来源保留历史版本，生成内容使用已确认事实及其限定条件。</span></div><div class="split"><section class="panel pad"><h2>创作任务</h2><div class="field"><label for="brieftitle">方案标题</label><input id="brieftitle" value="云衡 YH-20 产品规格与适用工况更新"></div><div class="grid2"><div class="field"><label for="briefasset">目标资产</label><input id="briefasset" value="官网 / 产品规格页"></div><div class="field"><label for="briefowner">负责人</label><input id="briefowner" value="内容团队 · 林晓"></div></div><div class="field"><label for="briefgoal">内容目标与必要信息</label><textarea id="briefgoal" rows="4">明确当前规格版本、适用温度与安装条件。&#10;说明新旧版本差异、生效日期及选型限制。&#10;提供产品资料入口，不省略参数对应的测试条件。</textarea></div><div class="field"><label for="briefboundary">事实与表达边界</label><textarea id="briefboundary" rows="3">使用审核通过的 2026 版规格及限定条件。&#10;不将实验条件下参数表达为全部工况保证。&#10;不编造竞品数据或平台推荐承诺。</textarea></div><h3 style="margin-top:20px">发布验收</h3><label class="check"><input type="checkbox" checked>参数、版本和限定条件已通过产品审核</label><label class="check"><input type="checkbox" checked>保留证据，正文明确适用范围及资料日期</label><label class="check"><input type="checkbox">发布后记录 URL、内容版本与发布时间</label></section><div><section class="panel pad"><div class="sectionhead"><h2>已关联的证据包</h2>${badge('可追溯','purple')}</div><div class="listitem"><strong>千问 · P-07 · 第 1 轮回答</strong><span class="sub">使用 120℃ 旧版参数</span><button class="textbtn" style="float:right" onclick="state.platform='千问';showView('evidence')">核对 →</button></div><div class="listitem"><strong>历史文章 · 快照 v1</strong><span class="sub">《云衡产品介绍（2024 版）》</span></div><div class="listitem"><strong>品牌确认事实 · F-2026-03</strong><span class="sub">0–150℃ · 指定安装方式</span> ${badge('已核实','teal')}</div><p class="sub">保留引用片段和限制，完整原文在证据页面查看。</p></section><section class="panel pad gap"><h2>平台目标分别验证</h2><div class="kv"><b>千问 · 主目标</b>${badge('参数准确性','purple')}</div><p class="sub">固定 P-07 和参数类问题，检查新规格与限定条件是否准确呈现。</p><div class="kv"><b>DeepSeek / Kimi</b>${badge('回归观察')}</div><p class="sub">检查参数是否出现新冲突，保留既有推荐表现。</p><div class="inspect" style="margin-top:15px"><strong>状态提醒</strong>创建草稿和发布页面不等于可见性改善，发布后进入固定队列复测。</div></section><div class="zero gap">外部文章纠错单独作为运营任务，记录资料提交与更新状态。</div></div></div>`}
function measure(){return head('MEASUREMENT','行动完成之后，逐平台验证变化','固定提示词版本与采样条件；主结果使用共同有效样本。',`<button class="btn" onclick="modal('复测队列与缺失处理','<p>共同有效样本：DeepSeek 56、千问 58、Kimi 54。主指标排除 12 个非共同有效配对位置，失败和条件变化单列。</p><p>未知账号条件的其他队列仅描述性展示。当前均为虚构示例。</p>')">查看队列条件</button><button class="btn primary" onclick="toast('示例：已安排下一轮复测，原型不调用设备')">安排下一轮复测</button>`)+`<section class="panel pad"><div class="sectionhead"><div><h2>工况说明与规格页更新 · EX-04</h2><div class="sub" style="margin-top:6px">基线 09.29 / 发布 10.06 / 本轮 10.13 · ACT-01、ACT-02</div></div><div class="pillset">${[7,14,28].map(n=>`<button class="${state.period===n?'active':''}" onclick="state.period=${n};showView('measure')">${n} 天观察</button>`).join('')}</div></div><div class="coverage"><span class="teal">● 资产已发布</span><span class="amber">● 样本不足，继续观察</span><span>yunheng.example.com / specs</span></div></section><div class="grid3 gap">${[['DeepSeek','14% → 29%','8/56 → 16/56','上升 +14.3 个百分点','teal','仍不能确认行动效果'],['千问','59% → 69%','34/58 → 40/58','上升 +10.3 个百分点','purple','参数核验：14/20 → 18/20'],['Kimi','50% → 46%','27/54 → 25/54','下降 −3.7 个百分点','blue','核查价格类问题与回答变化']].map(([p,v,n,s,c,d])=>`<section class="panel"><div class="platformhead"><b>${p}</b><span class="sub right">我方提及率</span></div><div class="result"><b class="${c}">${v}</b><div class="hint">${n} · 共同有效回答</div></div><div class="pad" style="padding:14px 18px"><p style="font-size:12px">观察到${s}</p><p class="sub">${d}</p>${badge('暂不足以判断改善','amber')}</div></section>`).join('')}</div><div class="notice warn">${icon('info')}<div>选定 ${state.period} 天观察窗口，原型仅提供 10.13 示意记录。区间估计和对照组分析待完成，不能将变化解释为行动导致的改善。</div></div><section class="panel pad"><div class="sectionhead"><h2>平台趋势与发布节点</h2><div class="legend"><span class="teal">● DeepSeek</span><span class="purple">● 千问</span><span class="blue">● Kimi</span></div></div><div class="chart"><svg viewBox="0 0 900 170" preserveAspectRatio="none" aria-label="平台趋势示意图"><path d="M10 132L230 123L460 112L670 96L890 88" fill="none" stroke="#00d4aa" stroke-width="2.5"/><path d="M10 74L230 70L460 58L670 51L890 44" fill="none" stroke="#b3a3ff" stroke-width="2.5"/><path d="M10 83L230 87L460 81L670 89L890 92" fill="none" stroke="#79b5ff" stroke-width="2.5"/><path d="M460 0v170" stroke="#8892ae" stroke-dasharray="4 5"/><text x="472" y="16" fill="#c4cad8" font-size="10">10.06 · 资产发布</text></svg></div><div class="chartlabels"><span>09.29 基线</span><span>10.02</span><span>10.06 发布</span><span>10.10</span><span>10.13 复测</span></div><div class="hint">趋势线为示意。正式结果同时展示区间、样本量、对照组与条件变化。</div></section><section class="panel gap">${table(['验证对象','执行状态','本轮观察','下一步'],[tr(['工况案例页',badge('已发布','teal'),'DeepSeek 提及率上升','继续采样，验证推荐率与对照组']),tr(['规格页与历史资料纠错',badge('已发布 / 纠错提交'),'千问核验正确断言 18/20','扩大核验覆盖，检查限定条件']),tr(['其他平台回归',badge('已观察','blue'),'Kimi 提及率略降','核查问题构成与回答变化'])])}<div class="footnote">本页是独立复测试点示例，执行状态不沿用当前待办列表。平台入口或条件变化时拆分队列，不用平均分代替逐平台结果。</div></section>`}
const views={overview,platforms,brands,sources,evidence,actions,brief,measure};
function showView(name){if(!views[name])name='overview';state.view=name;document.getElementById('main').innerHTML=views[name]()+footer();document.getElementById('crumb').textContent=labels[name];document.getElementById('nav').innerHTML=Object.entries(labels).map(([k,l])=>`<button class="navbtn ${name===k?'active':''}" onclick="showView('${k}')">${icon(k,18)}${l}${['sources','brands','evidence'].includes(k)?'<span class="new">新增</span>':''}</button>`).join('');history.replaceState(null,'','#'+name);window.scrollTo(0,0)}
let timer;function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.style.display='block';clearTimeout(timer);timer=setTimeout(()=>el.style.display='none',4000)}
let previousFocus;function modal(title,body,action=''){previousFocus=document.activeElement;document.getElementById('modaltitle').textContent=title;document.getElementById('modalbody').innerHTML=body;document.getElementById('modalactions').innerHTML=`<button class="btn" onclick="closeModal()">关闭</button>`+action;document.getElementById('modalback').style.display='flex';document.querySelector('.modal .close').focus()}
function closeModal(){document.getElementById('modalback').style.display='none';if(previousFocus?.isConnected)previousFocus.focus()}
function confirmBrand(){modal(state.tracked?'拓域 · 已重点监测':'确认拓域的项目身份',`<p>当前身份：${state.tracked?'已登记竞品':'候选竞品'}</p><p>业务重叠线索：高温监测场景；11 篇来源文章、49 条回答提及。</p><p class="sub">请结合产品范围确认。仅修改本项目角色，原始观测保留。</p>`,state.tracked?'':`<button class="btn primary" onclick="state.tracked=true;closeModal();showView('brands');toast('示例：拓域已加入本项目竞品名单')">确认作为竞品</button>`)}
function createBrief(){state.briefCreated=true;showView('brief');modal('内容方案草稿已创建','<p>已关联 ACT-02、千问主目标和其他平台回归观察。</p><p>证据与限定条件保留，下一步进入创作与审核。</p><p class="sub">示例交互，不提交到 ContentOS。</p>')}
function openArticle(title,platform,status){if(status==='全文'&&['高温工况选型与运行案例','云衡产品介绍（2024 版）','工业监测方案价格与配置'].includes(title)){state.platform=platform;showView('evidence')}else modal(title,`<p>当前状态：${status}</p><p>关联平台：${platform}</p><p class="sub">${status==='部分正文'?'已保存可取得的正文片段，未命中不能证明全文缺席。':status==='访问受限'?'尚未取得正文，保留链接及原因，可进入人工补采。':'链接已登记，等待后台补采任务。'}</p>`)}
function filterRows(value,type){let total=0;document.querySelectorAll(`[data-row="${type}"]`).forEach(el=>{let yes=el.textContent.toLowerCase().includes(value.toLowerCase());el.classList.toggle('hidden',!yes);if(yes)total++});document.getElementById('searchEmpty')?.remove();if(!total)document.querySelector('.table')?.insertAdjacentHTML('afterend','<div class="zero" id="searchEmpty">没有匹配内容，请调整搜索条件。</div>')}
document.getElementById('modalback').addEventListener('click',e=>{if(e.target.id==='modalback')closeModal()});document.addEventListener('keydown',e=>{let back=document.getElementById('modalback');if(back.style.display==='flex'){if(e.key==='Escape')closeModal();if(e.key==='Tab'){let controls=[...back.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});showView(location.hash.slice(1)||'overview');

function openSnapshot(){modal('文章原文快照',evidenceData[state.platform].paragraph+'<p class="sub">原型仅提供示例片段，正式页面提供权限内的持久化原文及段落定位。</p>')}